    ['cURL', extension_loaded('curl')],
    ['PharData или tar', class_exists('PharData') || !empty(shell_exec('which tar'))],
    ['Запись в директорию', is_writable(__DIR__)],
];
$allOk = true;
foreach ($checks as [$n,$ok]) { $allOk=$allOk&&$ok; ?>
<div class="flex justify-between py-2 border-b"><span><?=$n?></span><span class="<?=$ok?'text-green-600':'text-red-600'?>"><?=$ok?'✓':'✗'?></span></div>
<?php } ?>
